async function rateLimit(scope: string, subject: string, maximum: number) {
  const key = `daily:rate:${scope}:${subject.toLowerCase()}:${Math.floor(Date.now() / 60_000)}`; const count = await redis.incr(key); if (count === 1) await redis.expire(key, 60);
  if (count > maximum) { const error = new Error("Rate limit exceeded. Try again in one minute.") as Error & { statusCode: number }; error.statusCode = 429; throw error; }
}
async function validSignature(address: string, digest: string, signature: string, recovered?: string) {
  if (recovered?.toLowerCase() === address.toLowerCase()) return true;
  const code = await contracts.provider.getCode(address);
  if (code === "0x") return false;
  try { return (await contracts.provider.call({ to: address, data: ERC1271.encodeFunctionData("isValidSignature", [digest, signature]) })).slice(0, 10).toLowerCase() === "0x1626ba7e"; } catch { return false; }
}
async function requireProtocolAdmin(actor: string) {
  const registry = new Contract(contractAddresses.registry, ["function hasRole(bytes32,address) view returns (bool)"], contracts.provider);
  if (!await registry.hasRole(ZeroHash, actor)) { const error = new Error("Connected wallet lacks the on-chain Daily protocol-admin role.") as Error & { statusCode: number }; error.statusCode = 403; throw error; }
}
