function googleDriveConfig() { if (!config.googleDrive) { const error = new Error("Google Drive is not configured for this environment.") as Error & { statusCode: number }; error.statusCode = 503; throw error; } return config.googleDrive; }
async function googleDriveAccessToken(address: string) { const google = googleDriveConfig(); const refreshToken = await persistence.googleDriveRefreshToken(address); if (!refreshToken) { const error = new Error("Connect Google Drive before storing ciphertext.") as Error & { statusCode: number }; error.statusCode = 409; throw error; } const response = await fetch("https://oauth2.googleapis.com/token", { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ client_id: google.clientId, client_secret: google.clientSecret, refresh_token: refreshToken, grant_type: "refresh_token" }) }); if (!response.ok) { const error = new Error("Google Drive access-token refresh failed.") as Error & { statusCode: number }; error.statusCode = 502; throw error; } return (await response.json() as { access_token: string }).access_token; }
app.get("/v1/storage/google-drive/connect", async (request, reply) => { await request.jwtVerify(); const google = googleDriveConfig(); const actor = (request.user as { sub: string }).sub; const state = await reply.jwtSign({ sub: actor, purpose: "google-drive-oauth" }, { expiresIn: "10m" }); const url = new URL("https://accounts.google.com/o/oauth2/v2/auth"); url.search = new URLSearchParams({ client_id: google.clientId, redirect_uri: google.redirectUri, response_type: "code", scope: "https://www.googleapis.com/auth/drive.file openid email", access_type: "offline", prompt: "consent", state }).toString(); return { authorizationUrl: url.toString() }; });
app.get("/v1/storage/google-drive/callback", async (request, reply) => { const params = z.object({ code: z.string().min(1).optional(), state: z.string().min(1), error: z.string().optional() }).parse(request.query); if (params.error) return reply.code(400).type("text/plain").send(`Google Drive authorization failed: ${params.error}`); const google = googleDriveConfig(); let state: { sub: string; purpose?: string }; try { state = await app.jwt.verify(params.state) as { sub: string; purpose?: string }; } catch { return reply.code(400).type("text/plain").send("Google Drive authorization state is invalid or expired."); } if (state.purpose !== "google-drive-oauth" || !params.code) return reply.code(400).type("text/plain").send("Google Drive authorization request is invalid."); const tokenResponse = await fetch("https://oauth2.googleapis.com/token", { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ code: params.code, client_id: google.clientId, client_secret: google.clientSecret, redirect_uri: google.redirectUri, grant_type: "authorization_code" }) }); if (!tokenResponse.ok) return reply.code(502).type("text/plain").send("Google Drive token exchange failed."); const tokens = await tokenResponse.json() as { refresh_token?: string; access_token?: string; scope?: string }; if (!tokens.refresh_token) return reply.code(409).type("text/plain").send("Google did not issue a refresh token. Revoke the app in Google Account permissions, then reconnect."); let email: string | undefined; if (tokens.access_token) { const profile = await fetch("https://openidconnect.googleapis.com/v1/userinfo", { headers: { authorization: `Bearer ${tokens.access_token}` } }); if (profile.ok) email = (await profile.json() as { email?: string }).email; } await persistence.saveGoogleDriveConnection(state.sub, tokens.refresh_token, tokens.scope, email); const userUrl = new URL(config.allowedOrigins[0]); userUrl.searchParams.set("storage", "google-drive"); userUrl.searchParams.set("status", "connected"); return reply.redirect(userUrl.toString()); });
app.get("/v1/storage/google-drive", async request => { await request.jwtVerify(); const connection = await persistence.googleDriveConnection((request.user as { sub: string }).sub); return { connector: "google-drive", connected: Boolean(connection && !connection.revoked_at), ...(connection ? { email: connection.email, scope: connection.scope, connectedAt: connection.connected_at } : {}) }; });
