app.post("/v1/storage/google-drive/ciphertext", async (request, reply) => { await request.jwtVerify(); const body = z.object({ filename: z.string().regex(/^[A-Za-z0-9][A-Za-z0-9._-]{0,180}$/), ciphertextBase64: z.string().min(1).max(14_000_000) }).strict().parse(request.body); const actor = (request.user as { sub: string }).sub; const bytes = Buffer.from(body.ciphertextBase64, "base64"); if (!bytes.length || bytes.length > 10 * 1024 * 1024) return reply.code(413).send({ error: "Ciphertext must be between 1 byte and 10 MiB." }); const token = await googleDriveAccessToken(actor); const form = new FormData(); form.append("metadata", new Blob([JSON.stringify({ name: body.filename, mimeType: "application/octet-stream" })], { type: "application/json" })); form.append("file", new Blob([bytes], { type: "application/octet-stream" })); const upload = await fetch("https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart", { method: "POST", headers: { authorization: `Bearer ${token}` }, body: form }); if (!upload.ok) return reply.code(502).send({ error: "Google Drive ciphertext upload failed." }); const file = await upload.json() as { id: string }; return reply.code(201).send({ id: file.id, filename: body.filename, bytes: bytes.length }); });
app.get("/v1/storage/google-drive/ciphertext/:id", async (request, reply) => { await request.jwtVerify(); const id = (request.params as { id: string }).id; if (!/^[A-Za-z0-9_-]{10,200}$/.test(id)) return reply.code(400).send({ error: "Invalid Google Drive file ID." }); const token = await googleDriveAccessToken((request.user as { sub: string }).sub); const download = await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(id)}?alt=media`, { headers: { authorization: `Bearer ${token}` } }); if (!download.ok) return reply.code(502).send({ error: "Google Drive ciphertext download failed." }); reply.header("content-type", "application/octet-stream"); return reply.send(Buffer.from(await download.arrayBuffer())); });
