app.post("/v1/ccip/records", async (request, reply) => {
  await request.jwtVerify();
  const body = z.object({ name: z.string().min(3).max(255), extraData: z.string().regex(/^0x[0-9a-fA-F]*$/).max(262_146), result: z.string().regex(/^0x[0-9a-fA-F]*$/).max(1_048_578) }).strict().parse(request.body);
  const actor = (request.user as { sub: string }).sub;
  const resolved = await contracts.resolve(body.name);
  if (resolved.owner.toLowerCase() !== actor.toLowerCase()) return reply.code(403).send({ error: "Only the current on-chain name owner may publish this off-chain resolver record." });
  const node = resolved.node;
  const expected = abiCoder.encode(["bytes", "bytes"], [abiCoder.decode(["bytes", "bytes"], body.extraData)[0], abiCoder.decode(["bytes", "bytes"], body.extraData)[1]]);
  if (expected.toLowerCase() !== body.extraData.toLowerCase()) return reply.code(400).send({ error: "CCIP extraData must be canonical abi.encode(bytes name,bytes data)." });
  const requestHash = keccak256(body.extraData);
  await persistence.upsertCcipRecord({ requestHash, node, owner: actor, extraData: body.extraData, result: body.result });
  return reply.code(201).send({ requestHash, node });
});
app.post("/v1/ccip/resolve", async (request, reply) => {
  if (!ccipGateway) return reply.code(503).send({ error: "CCIP gateway signing is not configured." });
  const body = z.object({ sender: z.string().refine(isAddress, "Invalid resolver address."), data: z.string().regex(/^0x[0-9a-fA-F]*$/).max(262_146) }).strict().parse(request.body);
  const record = await persistence.ccipRecord(keccak256(body.data));
  if (!record || record.extra_data.toLowerCase() !== body.data.toLowerCase()) return reply.code(404).send({ error: "No off-chain resolver record exists for this request." });
  const digest = solidityPackedKeccak256(["address", "uint256", "bytes", "bytes"], [body.sender, BigInt(DAILY_NETWORKS.sepolia.chainId), body.data, record.result]);
  const signature = await ccipGateway.signMessage(getBytes(digest));
  return { data: abiCoder.encode(["bytes", "bytes"], [record.result, signature]), signer: ccipGateway.address };
});
app.post("/v1/premium-requests", async (request, reply) => { await request.jwtVerify(); const body = z.object({ name: z.string().min(3).max(128), durationYears: z.number().int().min(1).max(10), reason: z.string().trim().min(10).max(2000), note: z.string().trim().min(1).max(5000), evidenceReference: z.string().uuid().optional() }).strict().parse(request.body); const name = normalizeName(body.name); const [label, tld] = name.split("."); const result = (await contracts.search(label)).find(value => value.tld === tld); if (result?.status !== "premium") return reply.code(409).send({ error: "Only currently catalogued premium names can use this request workflow." }); const actor = (request.user as { sub: string }).sub; await rateLimit("premium-request", actor, 10); return reply.code(201).send(await persistence.createPremiumRequest({ name, applicant: actor, durationYears: body.durationYears, reason: body.reason, note: body.note, evidenceReference: body.evidenceReference })); });
