app.post("/v1/identity-links", async (request, reply) => { await request.jwtVerify(); const primary = (request.user as { sub: string }).sub; const body = z.object({ linkedAddress: z.string().refine(isAddress, "Invalid linked wallet."), signature: z.string().min(2), deadline: z.number().int().positive() }).strict().parse(request.body); if (body.deadline < Math.floor(Date.now() / 1000)) return reply.code(400).send({ error: "Identity-link signature has expired." }); if (primary.toLowerCase() === body.linkedAddress.toLowerCase()) return reply.code(400).send({ error: "A wallet cannot link itself." }); const value = { primary, linked: body.linkedAddress, deadline: BigInt(body.deadline) }; let recovered: string | undefined; try { recovered = verifyTypedData(identityLinkDomain, IDENTITY_LINK_TYPES, value, body.signature); } catch { /* ERC-1271 wallets are checked below. */ } if (!await validSignature(body.linkedAddress, TypedDataEncoder.hash(identityLinkDomain, IDENTITY_LINK_TYPES, value), body.signature, recovered)) return reply.code(401).send({ error: "Linked-wallet proof is invalid." }); return persistence.linkIdentity(primary, body.linkedAddress, body.signature, body.deadline); });
