app.post("/v1/marketing/campaigns/:campaignId/refund", async (request, reply) => { await request.jwtVerify(); const actor = (request.user as { sub: string }).sub; const campaignId = (request.params as { campaignId: string }).campaignId; const { transactionHash } = z.object({ transactionHash: z.string().regex(/^0x[a-fA-F0-9]{64}$/) }).strict().parse(request.body); if (!/^0x[a-fA-F0-9]{64}$/.test(campaignId)) return reply.code(400).send({ error: "Invalid campaign ID." }); const receipt = await contracts.provider.getTransactionReceipt(transactionHash); if (!receipt || receipt.status !== 1) return reply.code(409).send({ error: "Refund transaction is missing or unsuccessful." }); const found = receipt.logs.some(log => { if (log.address.toLowerCase() !== SEPOLIA_CONTRACTS.campaignEscrow.toLowerCase()) return false; try { const parsed = ESCROW_EVENTS.parseLog(log); return parsed?.name === "RefundClaimed" && String(parsed.args.campaignId).toLowerCase() === campaignId.toLowerCase(); } catch { return false; } }); if (!found) return reply.code(409).send({ error: "Transaction does not contain the requested refund event." }); return persistence.markCampaignRefunded(campaignId, actor); });
