async function requireMailboxOwner(node: string, actor: string) { const mailbox = await contracts.mailboxByNode(node); if (mailbox.owner.toLowerCase() !== actor.toLowerCase()) throw new Error("Only the current on-chain mailbox owner may access these encrypted-mail metadata records."); return mailbox; }
const keyHash = (publicKey: Record<string, unknown>) => `0x${createHash("sha256").update(JSON.stringify(publicKey)).digest("hex")}`;
app.post("/v1/mailboxes", async (request, reply) => {
  await request.jwtVerify();
  const body = z.object({ namehash: z.string().regex(/^0x[a-fA-F0-9]{64}$/), publicKey: z.record(z.unknown()).refine(value => value.kty === "EC" && typeof value.x === "string" && typeof value.y === "string", "A P-256 public JWK is required."), keyVersion: z.number().int().positive() }).parse(request.body);
  const mailbox = await requireMailboxOwner(body.namehash, (request.user as { sub: string }).sub);
  if (!mailbox.resolver || mailbox.mailKeyHash === ZeroHash) return reply.code(409).send({ error: "Publish the mailbox key record on-chain before registering its public key." });
  if (mailbox.mailKeyVersion !== body.keyVersion || keyHash(body.publicKey).toLowerCase() !== mailbox.mailKeyHash.toLowerCase()) return reply.code(409).send({ error: "The public key does not match the current on-chain key hash and version." });
  await persistence.registerMailbox(body.namehash, mailbox.owner, mailbox.mailKeyHash, mailbox.mailKeyVersion, body.publicKey);
  return reply.code(201).send({ namehash: body.namehash.toLowerCase(), keyHash: mailbox.mailKeyHash, keyVersion: mailbox.mailKeyVersion });
});
app.get("/v1/mailboxes/:namehash", async (request, reply) => {
  const namehash = (request.params as { namehash: string }).namehash;
  if (!/^0x[a-fA-F0-9]{64}$/.test(namehash)) return reply.code(400).send({ error: "Invalid mailbox namehash." });
  const onChain = await contracts.mailboxByNode(namehash); const record = await persistence.mailboxPublicKey(namehash);
  if (!record || !record.public_key || record.public_key_hash.toLowerCase() !== onChain.mailKeyHash.toLowerCase() || record.key_version !== onChain.mailKeyVersion) return reply.code(404).send({ error: "Recipient has not published an available current public mailbox key." });
  return { namehash: record.namehash, keyHash: record.public_key_hash, keyVersion: record.key_version, publicKey: record.public_key };
});
app.post("/v1/mail/envelopes", async (request, reply) => { await request.jwtVerify(); if (await persistence.mailRelayPaused()) return reply.code(503).send({ error: "Daily Mail relay is temporarily paused." }); const body = z.object({ from: z.string().refine(isAddress, "Invalid sender address."), recipientNamehash: z.string().regex(/^0x[a-fA-F0-9]{64}$/), ciphertext: z.string().min(1).max(5_000_000), signature: z.string().min(2), nonce: z.string().regex(/^\d+$/), deadline: z.number().int().positive() }).parse(request.body); await rateLimit("mail-envelope", body.from, 60); const actor = (request.user as { sub: string }).sub; if (actor.toLowerCase() !== body.from.toLowerCase()) return reply.code(403).send({ error: "Envelope sender must match the authenticated wallet." }); const value = { from: body.from, toNamehash: body.recipientNamehash, ciphertextHash: `0x${(await import("node:crypto")).createHash("sha256").update(body.ciphertext).digest("hex")}`, nonce: BigInt(body.nonce), deadline: BigInt(body.deadline) }; let recovered: string | undefined; try { recovered = verifyTypedData(mailDomain, MAIL_ENVELOPE_TYPES, value, body.signature); } catch { /* ERC-1271 is checked below. */ } if (!await validSignature(actor, TypedDataEncoder.hash(mailDomain, MAIL_ENVELOPE_TYPES, value), body.signature, recovered)) return reply.code(401).send({ error: "Daily Mail EIP-712 envelope signature is invalid." }); const mailbox = await contracts.mailboxByNode(body.recipientNamehash); if (!mailbox.resolver || mailbox.mailKeyHash === ZeroHash) return reply.code(409).send({ error: "Recipient has not activated encrypted Daily Mail." }); return reply.code(202).send(await persistence.submitMail(body, { owner: mailbox.owner, keyHash: mailbox.mailKeyHash, keyVersion: mailbox.mailKeyVersion })); });
