app.post("/v1/mail/:id/:action", async (request, reply) => { await request.jwtVerify(); const { id, action } = request.params as { id: string; action: string }; const details = await persistence.messageSender(id); if (!details) return reply.code(404).send({ error: "Encrypted-mail metadata was not found." }); const actor = (request.user as { sub: string }).sub; await requireMailboxOwner(details.recipient_namehash, actor); if (action === "block") { await persistence.blockSender(details.recipient_namehash, details.sender_address); return { blocked: details.sender_address }; } if (action === "report") { const reason = z.object({ reason: z.string().max(1000).optional() }).parse(request.body ?? {}).reason; await persistence.reportSpam(id, actor, reason); return { reported: true }; } if (!["read", "acknowledge", "archive", "delete"].includes(action)) return reply.code(400).send({ error: "Unsupported mail action." }); if (action === "acknowledge") { const body = z.object({ signature: z.string().min(2), deadline: z.number().int().positive() }).strict().parse(request.body); if (body.deadline < Math.floor(Date.now() / 1000)) return reply.code(400).send({ error: "Acknowledgement signature has expired." }); const value = { messageId: id, recipientNamehash: details.recipient_namehash, deadline: BigInt(body.deadline) }; let recovered: string | undefined; try { recovered = verifyTypedData(mailDomain, MAIL_ACKNOWLEDGEMENT_TYPES, value, body.signature); } catch { /* Contract wallets are validated through ERC-1271. */ } if (!await validSignature(actor, TypedDataEncoder.hash(mailDomain, MAIL_ACKNOWLEDGEMENT_TYPES, value), body.signature, recovered)) return reply.code(401).send({ error: "Acknowledgement signature is invalid." }); return persistence.updateMail(id, details.recipient_namehash, "acknowledge", body.signature); } return persistence.updateMail(id, details.recipient_namehash, action as "read" | "archive" | "delete"); });
